import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.C-si7TFR.js";const u=JSON.parse('{"title":"企微 Agent 遥控","description":"","frontmatter":{"title":"企微 Agent 遥控"},"headers":[],"relativePath":"zh/guide/remote-control.md","filePath":"zh/guide/remote-control.md"}'),l={name:"zh/guide/remote-control.md"};function n(i,e,s,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="企微-agent-遥控" tabindex="-1">企微 Agent 遥控 <a class="header-anchor" href="#企微-agent-遥控" aria-label="Permalink to &quot;企微 Agent 遥控&quot;">​</a></h1><p>企微遥控通过长连接通道，让获准的企业微信用户与指定 Agent 对话。它不是旧机器人触发器，也不是单纯的企业微信消息发送节点。</p><h2 id="前提" tabindex="-1">前提 <a class="header-anchor" href="#前提" aria-label="Permalink to &quot;前提&quot;">​</a></h2><ul><li>有可用的 Agent 和模型配置。</li><li>已在企业微信管理后台准备支持该通道的 Bot ID 与长连接 Secret。</li><li>当前网络允许建立所需长连接；能否连接以通道状态为准。</li><li>了解 Agent 的工具、工作目录和可访问数据范围。</li></ul><h2 id="添加通道" tabindex="-1">添加通道 <a class="header-anchor" href="#添加通道" aria-label="Permalink to &quot;添加通道&quot;">​</a></h2><ol><li>从 Agent 卡片的远程通道入口，或工作台顶部入口进入远程通道管理。</li><li>选择<strong>添加遥控</strong>，选择 Agent 并填写通道名称。</li><li>填入 Bot ID 和 Secret。不要把真实值放入文档、截图或公开配置。</li><li>配置用户白名单，明确允许使用该 Agent 的用户；只有确实理解风险时才考虑 <code>*</code>。</li><li>选择<strong>连接并保存</strong>，确认通道进入可用状态后，用白名单中的账号发送一个无副作用测试消息。</li></ol><p>通道的启用／停用控制远程访问。会话可在 Web 端继续查看，但并不意味着远程用户天然拥有 Web 管理权限。</p><h2 id="与其他企业微信能力的区别" tabindex="-1">与其他企业微信能力的区别 <a class="header-anchor" href="#与其他企业微信能力的区别" aria-label="Permalink to &quot;与其他企业微信能力的区别&quot;">​</a></h2><ul><li><strong>企微遥控</strong>：接收远程用户指令，驱动 Agent，回复对话结果。</li><li><strong>旧企微机器人触发器</strong>：历史工作流入口，新建入口已隐藏。</li><li><strong>发送企业微信消息节点</strong>：工作流向外发送消息，不等于建立 Agent 遥控。</li></ul><h2 id="安全与排查" tabindex="-1">安全与排查 <a class="header-anchor" href="#安全与排查" aria-label="Permalink to &quot;安全与排查&quot;">​</a></h2><p>白名单是重要边界，但不应替代最小工具授权。通道异常时先停用，检查 Bot 配置、白名单、网络和通道错误信息，再检查 Agent 会话与工具结果。Secret 泄露后应在对应平台轮换，不能只删除截图。</p>',11)])])}const _=t(l,[["render",n]]);export{u as __pageData,_ as default};
